+import { initTRPC } from '@trpc/server';
+import { describe, expect, it } from 'vitest';
+import { z } from 'zod';
+import { createTRPCClient } from '../createTRPCClient';
+import { TRPCClientError } from '../TRPCClientError';
+import { localLink } from './localLink';
+
+describe('localLink', () => {
+  it('should be able to run a query', async () => {
+    const t = initTRPC.create();
+    const router = t.router({
+      hello: t.procedure.query(() => 'world'),
+    });
+
+    const client = createTRPCClient<typeof router>({
+      links: [
+        localLink({
+          router,
+        }),
+      ],
+    });
+
+    const res = await client.hello.query();
+    expect(res).toBe('world');
+  });
+
+  it('should be able to run a query with context', async () => {
+    const t = initTRPC.context<{ user: string }>().create();
+    const router = t.router({
+      whoami: t.procedure.query(({ ctx }) => ctx.user),
+    });
+
+    const client = createTRPCClient<typeof router>({
+      links: [
+        localLink({
+          router,
+          createContext: () => ({ user: 'alice' }),
+        }),
+      ],
+    });
+
+    const res = await client.whoami.query();
+    expect(res).toBe('alice');
+  });
+
+  it('should apply transformers', async () => {
+    const transformer = {
+      serialize: (v: any) => v + ' [serialized]',
+      deserialize: (v: any) => v + ' [deserialized]',
+    };
+    const t = initTRPC.create({
+      transformer,
+    });
+    const router = t.router({
+      hello: t.procedure.query(() => 'world'),
+    });
+
+    const client = createTRPCClient<typeof router>({
+      links: [
+        localLink({
+          router,
+          transformer,
+        }),
+      ],
+    });
+
+    const res = await client.hello.query();
+    expect(res).toBe('world [serialized] [deserialized]');
+  });
+
+  it('should apply transformers to input', async () => {
+    const transformer = {
+      serialize: (v: any) => v + ' [serialized]',
+      deserialize: (v: any) => v + ' [deserialized]',
+    };
+    const t = initTRPC.create({
+      transformer,
+    });
+    const router = t.router({
+      hello: t.procedure.input(z.string()).query(({ input }) => input),
+    });
+
+    const client = createTRPCClient<typeof router>({
+      links: [
+        localLink({
+          router,
+          transformer,
+        }),
+      ],
+    });
+
+    const res = await client.hello.query('world');
+    expect(res).toBe(
+      'world [serialized] [deserialized] [serialized] [deserialized]',
+    );
+  });
+
+  it('should propagate errors', async () => {
+    const t = initTRPC.create();
+    const router = t.router({
+      err: t.procedure.query(() => {
+        throw new Error('some error');
+      }),
+    });
+
+    const client = createTRPCClient<typeof router>({
+      links: [localLink({ router })],
+    });
+
+    await expect(client.err.query()).rejects.toThrow(TRPCClientError);
+    await expect(client.err.query()).rejects.toMatchObject({
+      message: 'some error',
+    });
+  });
+
+  it('should call onError', async () => {
+    const t = initTRPC.create();
+    const router = t.router({
+      err: t.procedure.query(() => {
+        throw new Error('some error');
+      }),
+    });
+
+    const onError = vi.fn();
+    const client = createTRPCClient<typeof router>({
+      links: [
+        localLink({
+          router,
+          onError,
+        }),
+      ],
+    });
+
+    await expect(client.err.query()).rejects.toThrow();
+    expect(onError).toHaveBeenCalledTimes(1);
+    expect(onError).toHaveBeenCalledWith(
+      expect.objectContaining({
+        path: 'err',
+        type: 'query',
+        error: expect.any(TRPCClientError),
+      }),
+    );
+  });
+});
diff --git a/packages/client/src/links/localLink.ts b/packages/client/src/links/localLink.ts
new file mode 100644
index 0000000000..8a631bd2bc
--- /dev/null
+++ b/packages/client/src/links/localLink.ts
@@ -0,0 +1,132 @@
+import { observable } from '@trpc/server/observable';
+import type {
+  AnyRouter,
+  CreateContextCallback,
+  inferRouterContext,
+  MaybePromise,
+} from '@trpc/server/unstable-core-do-not-import';
+import {
+  callProcedure as callTRPCProcedure,
+  transformResult,
+} from '@trpc/server/unstable-core-do-not-import';
+import { getTransformer } from '../internals/transformer';
+import type { TransformerOptions } from '../internals/transformer';
+import { TRPCClientError } from '../TRPCClientError';
+import type { Operation, TRPCLink } from './types';
+
+/**
+ * @public
+ */
+export type LocalLinkOptions<TRouter extends AnyRouter> = {
+  router: TRouter;
+  /**
+   * Optional callback to handle errors
+   */
+  onError?: (opts: {
+    path: string;
+    type: Operation['type'];
+    input: unknown;
+    error: TRPCClientError<TRouter>;
+  }) => void;
+} & CreateContextCallback<
+  inferRouterContext<TRouter>,
+  (opts: { op: Operation }) => MaybePromise<inferRouterContext<TRouter>>
+> &
+  TransformerOptions<TRouter['_def']['_config']['$types']>;
+
+/**
+ * @see https://trpc.io/docs/v11/client/links/localLink
+ * @public
+ */
+export function localLink<TRouter extends AnyRouter>(
+  opts: LocalLinkOptions<TRouter>,
+): TRPCLink<TRouter> {
+  const _transformer = getTransformer(opts.transformer);
+  return () =>
+    ({ op }) =>
+      observable((observer) => {
+        const { type, path, input, signal } = op;
+
+        const promise = (async () => {
+          try {
+            const transformedInput = _transformer.input.serialize(input);
+            const deserializedInput =
+              opts.router._def._config.transformer.input.deserialize(
+                transformedInput,
+              );
+
+            const ctx = opts.createContext
+              ? await (opts as any).createContext({ op })
+              : undefined;
+
+            const result = await callTRPCProcedure({
+              router: opts.router,
+              path,
+              type,
+              input: deserializedInput,
+              ctx,
+              signal,
+              getRawInput: async () => deserializedInput,
+            });
+
+            if (type === 'subscription') {
+              // TODO: Handle subscriptions in next facet
+              const error = TRPCClientError.from(
+                new Error('Subscriptions are not yet implemented in localLink'),
+              );
+              opts.onError?.({
+                path,
+                type,
+                input,
+                error,
+              });
+              observer.error(error);
+              return;
+            }
+
+            const serialized =
+              opts.router._def._config.transformer.output.serialize(result);
+
+            const transformed = transformResult(
+              {
+                result: {
+                  type: 'data',
+                  data: serialized,
+                },
+              },
+              _transformer.output,
+            );
+
+            if (!transformed.ok) {
+              const error = TRPCClientError.from(transformed.error);
+              opts.onError?.({
+                path,
+                type,
+                input,
+                error,
+              });
+              observer.error(error);
+              return;
+            }
+
+            observer.next({
+              result: transformed.result,
+            });
+            observer.complete();
+          } catch (cause) {
+            const error = TRPCClientError.from(cause);
+            opts.onError?.({
+              path,
+              type,
+              input,
+              error,
+            });
+            observer.error(error);
+          }
+        })();
+
+        return () => {
+          // noop
+        };
+      });
+}

